description:
fgfgfgfgfgf// src/includes/chat/getSidebarScripts.js

export function getSidebarScripts() {
 return `<script>
 document.addEventListener('DOMContentLoaded', () => {
 const btnToggle = document.getElementById('btnToggleChatMobile');
 const sidebar = document.getElementById('chatUsers');
 const iconChat = document.getElementById('iconChatMobile');
 const iconClose = document.getElementById('iconCloseMobile');

 if (btnToggle && sidebar) {
 btnToggle.addEventListener('click', (e) => {
 e.stopPropagation();
 const isVisible = sidebar.classList.toggle('show');
 if (iconChat) iconChat.style.display = isVisible ? 'none' : 'block';
 if (iconClose) iconClose.style.display = isVisible ? 'block' : 'none';
 });
 }
 });

 window.ChatSidebarState = {
 offset: 0,
 limit: 15,
 loading: false,
 allLoaded: false,
 activeTab: 'all',
 searchQuery: '',
 totalUnread: 0,
 sortMethod: 'defaultSort'
 };

 window.handleRealtimeNewChat = function(conv) {
 if (!conv) return;
 const isActive = window.ChatGlobalState && window.ChatGlobalState.currentConversationId == conv.conversation_id;
 if (isActive) {
 conv.unread_count = 0;
 } else {
 const listContainer = document.getElementById("chatListContainer");
 if (listContainer) {
 const existing = listContainer.querySelector('[data-conversation-id="' + conv.conversation_id + '"]');
 if (existing) {
 const badge = existing.querySelector(".msg-unread-badge");
 const currentCount = badge ? parseInt(badge.dataset.count) || 0 : 0;
 conv.unread_count = currentCount + 1;
 } else {
 conv.unread_count = 1;
 }
 }
 window.ChatSidebarState.totalUnread += 1;
 window.updateTopBadgeUI();
 }
 window.addOrUpdateConversation(conv, true);
 };

 window.updateTopBadgeUI = function() {
 const topBadge = document.getElementById('chatTotalCounter');
 if (!topBadge) return;
 if (window.ChatSidebarState.totalUnread > 0) {
 topBadge.className = "badge bg-danger rounded-pill px-2 py-1 shadow-sm";
 topBadge.innerHTML = window.ChatSidebarState.totalUnread + " Unread";
 } else {
 topBadge.className = "badge bg-light text-muted border rounded-pill px-2 py-1";
 topBadge.innerHTML = "All caught up";
 }
 };

 window.switchSidebarTab = function(tab) {
 window.ChatSidebarState.activeTab = tab;
 document.querySelectorAll('.chat-tab').forEach(el => el.classList.remove('active'));
 const activeEl = document.querySelector('.chat-tab[data-tab="' + tab + '"]');
 if (activeEl) activeEl.classList.add('active');

 window.ChatSidebarState.offset = 0;
 window.ChatSidebarState.allLoaded = false;
 document.getElementById("chatListContainer").innerHTML = '';
 window.loadConversations();
 };

 window.setChatSort = function(sortMethod) {
 window.ChatSidebarState.sortMethod = sortMethod;
 window.ChatSidebarState.offset = 0;
 window.ChatSidebarState.allLoaded = false;
 document.getElementById("chatListContainer").innerHTML = '';
 window.loadConversations();
 };

 let searchDebounce;
 window.filterSidebar = function(val) {
 clearTimeout(searchDebounce);
 searchDebounce = setTimeout(() => {
 window.ChatSidebarState.searchQuery = val.trim().toLowerCase();
 window.ChatSidebarState.offset = 0;
 window.ChatSidebarState.allLoaded = false;
 document.getElementById("chatListContainer").innerHTML = '';
 window.loadConversations();
 }, 300);
 };

 window.blockChat = function(convId, isSpamCurrently) {
 Swal.fire({
 title: isSpamCurrently ? "Restore Chat?" : "Mark as Spam?",
 text: isSpamCurrently ? "Move this conversation back to your inbox?" : "Move this conversation to the Spam folder?",
 icon: "warning",
 showCancelButton: true,
 confirmButtonColor: isSpamCurrently ? "#10B981" : "#F59E0B",
 confirmButtonText: "Yes"
 }).then(async (result) => {
 if (result.isConfirmed) {
 const formData = new FormData();
 formData.append("action", "togglespam");
 formData.append("conversation_id", convId);

 try {
 const res = await fetch("/api_web/send_msg", { method: "POST", body: formData });
 const data = await res.json();
 if (data.success) {
 const row = document.querySelector('[data-conversation-id="' + convId + '"]');
 if (row) {
 const badge = row.querySelector(".msg-unread-badge");
 if (badge) {
 const count = parseInt(badge.dataset.count) || 0;
 window.ChatSidebarState.totalUnread = Math.max(0, window.ChatSidebarState.totalUnread - count);
 window.updateTopBadgeUI();
 }
 row.remove();
 }
 Swal.fire({ title: "Success", text: isSpamCurrently ? "Restored to Inbox" : "Moved to Spam", icon: "success", timer: 1500, showConfirmButton: false });
 }
 } catch (err) {}
 }
 });
 };

 window.blockUser = function() {
 Swal.fire({ title: "Coming Soon", text: "The 'Block User' feature will be available in the next update.", icon: "info", confirmButtonColor: "#0d6efd" });
 };

 window.deleteConversation = function(convId) {
 Swal.fire({
 title: "Delete Chat?",
 text: "This will permanently delete this conversation. This cannot be undone.",
 icon: "error",
 showCancelButton: true,
 confirmButtonColor: "#EF4444",
 confirmButtonText: "Delete"
 }).then(async (result) => {
 if (result.isConfirmed) {
 const formData = new FormData();
 formData.append("action", "deletechat");
 formData.append("conversation_id", convId);

 try {
 await fetch("/api_web/send_msg", { method: "POST", body: formData });
 const row = document.querySelector('[data-conversation-id="' + convId + '"]');
 if (row) {
 const badge = row.querySelector(".msg-unread-badge");
 if (badge) {
 const count = parseInt(badge.dataset.count) || 0;
 window.ChatSidebarState.totalUnread = Math.max(0, window.ChatSidebarState.totalUnread - count);
 window.updateTopBadgeUI();
 }
 row.remove();
 }

 if (window.ChatGlobalState && window.ChatGlobalState.currentConversationId == convId) {
 document.getElementById('chatBody').innerHTML = '';
 document.getElementById('chatHeaderInfo').innerHTML = '<div class="fw-bold text-dark" style="font-size: 14px;">Select a conversation</div>';
 }
 Swal.fire({ title: "Deleted", text: "Conversation removed.", icon: "success", timer: 1500, showConfirmButton: false });
 } catch(e) {}
 }
 });
 };

 document.addEventListener("click", function(e) {
 const item = e.target.closest(".user-item");
 if (!item || e.target.closest('.dropdown')) return;
 const convId = item.dataset.conversationId;
 if (!convId) return;

 if (typeof window.selectUser === 'function') {
 window.selectUser(item, convId);
 }

 const sidebar = document.getElementById('chatUsers');
 if (sidebar && sidebar.classList.contains('show') && window.innerWidth <= 768) {
 sidebar.classList.remove('show');
 const iconChat = document.getElementById('iconChatMobile');
 const iconClose = document.getElementById('iconCloseMobile');
 if (iconChat) iconChat.style.display = 'block';
 if (iconClose) iconClose.style.display = 'none';
 }
 });

 window.loadConversations = async function(silent = false) {
 const state = window.ChatSidebarState;
 if (state.loading || state.allLoaded) return;
 state.loading = true;

 const loader = document.getElementById("convLoader");
 const listContainer = document.getElementById("chatListContainer");

 if (!listContainer) {
 state.loading = false;
 return;
 }
 if (loader && !silent) loader.classList.remove('d-none');

 const formData = new FormData();
 formData.append("action", "loadconversations");
 formData.append("limit", state.limit);
 formData.append("offset", state.offset);
 formData.append("sort", state.sortMethod);

 if (state.searchQuery) formData.append("search", state.searchQuery);
 if (state.activeTab === 'unread') formData.append("tab", "1");
 else if (state.activeTab === 'spam') formData.append("tab", "2");
 else formData.append("tab", "0");

 try {
 const res = await fetch("/api_web/send_msg", { method: "POST", body: formData });
 let convs = await res.json();

 if (convs.error) {
 state.allLoaded = true;
 state.loading = false;
 if (loader) loader.classList.add('d-none');
 return;
 }

 if (!Array.isArray(convs)) convs = convs ? [convs] : [];

 if (convs.length === 0) {
 state.allLoaded = true;
 if (state.offset === 0 && !silent) {
 const msgText = state.activeTab === 'spam' ? 'No spam chats' : (state.activeTab === 'unread' ? 'No unread messages' : 'No chats found');
 listContainer.innerHTML = '<div class="text-center mt-5 text-muted p-3"><svg width="40" height="40" fill="#cbd5e1" class="mb-2" viewBox="0 0 16 16"><path d="M2 2a2 2 0 0 0-2 2v9.586l2-2V4a1 1 0 0 1 1-1h11a1 1 0 0 1 1 1v7a1 1 0 0 1-1 1H5.414l-2 2H14a2 2 0 0 0 2-2V4a2 2 0 0 0-2-2H2z"/></svg><p class="small m-0">' + msgText + '</p></div>';
 }
 } else {
 if (state.offset === 0 && state.activeTab === 'all' && !state.searchQuery) {
 state.totalUnread = convs.reduce((sum, c) => sum + Number(c.unread_count || 0), 0);
 window.updateTopBadgeUI();
 }

 convs.forEach(c => window.addOrUpdateConversation(c, false));
 state.offset += convs.length;
 if (convs.length < state.limit) state.allLoaded = true;
 }
 } catch (err) { state.allLoaded = true; }

 state.loading = false;
 if (loader) loader.classList.add('d-none');
 };

 window.addOrUpdateConversation = function(conv, bumpToTop = false) {
 const listContainer = document.getElementById("chatListContainer");
 if (!listContainer) return;

 let existing = listContainer.querySelector('[data-conversation-id="' + conv.conversation_id + '"]');

 let snippet = conv.last_message || "New Conversation";
 if (snippet.length > 32) snippet = snippet.substring(0, 32) + "...";
 const isUnread = conv.unread_count > 0;
 const adImg = conv.ad_image || "the original listing
 const userPic = conv.other_userpic || "the original listing

 let timeStr = "";
 if (conv.last_message_at) {
 const dt = new Date(conv.last_message_at);
 const now = new Date();
 const diffMins = Math.floor((now - dt) / 60000);
 if (diffMins < 1) timeStr = 'now';
 else if (diffMins < 60) timeStr = diffMins + 'm';
 else if (Math.floor(diffMins / 60) < 24) timeStr = Math.floor(diffMins / 60) + 'h';
 else if (Math.floor(diffMins / 1440) < 7) timeStr = Math.floor(diffMins / 1440) + 'd';
 else timeStr = dt.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
 }

 const badgeHtml = isUnread
 ? '<span class="badge rounded-pill shadow-sm msg-unread-badge" data-count="' + conv.unread_count + '" style="background-color: #EF4444 !important; color: #ffffff !important; font-size: 11px; padding: 4px 7px;">' + conv.unread_count + '</span>'
 : '';

 let statusBadge = '';
 if (conv.ad_status && conv.ad_status.toLowerCase() !== 'active') {
 const s = conv.ad_status.toLowerCase();
 let color = '#007AFF';
 let text = s.toUpperCase();
 if (s === 'edit' || s === 'pending') { color = '#F59E0B'; text = 'PENDING'; }
 else if (s === 'rejected' || s === 'deleted') { color = '#EF4444'; }
 else if (s === 'sold' || s === 'inactive') { color = '#64748B'; }

 statusBadge = '<span style="font-size: 9px; font-weight: 800; letter-spacing: 0.3px; color: ' + color + '; background-color: ' + color + '1E; border: 1px solid ' + color + '4D; padding: 2px 6px; border-radius: 6px; margin-left: 6px;">' + text + '</span>';
 }

 const spamAction = conv.is_spam
 ? '<li><a class="dropdown-item text-success d-flex align-items-center gap-2 py-2" href="#" onclick="event.stopPropagation(); window.blockChat(\\'' + conv.conversation_id + '\\', true)">✅ Restore from Spam</a></li>'
 : '<li><a class="dropdown-item text-warning d-flex align-items-center gap-2 py-2" href="#" onclick="event.stopPropagation(); window.blockChat(\\'' + conv.conversation_id + '\\', false)">🚫 Mark as Spam</a></li>';

 const blockAction = '<li><a class="dropdown-item text-secondary d-flex align-items-center gap-2 py-2" href="#" onclick="event.stopPropagation(); window.blockUser()">⛔ Block User</a></li>';

 const html = [
 '<div class="ad-thumb-box">',
 '<img src="', adImg, '" alt="Ad" class="ad-thumb">',
 '<img src="', userPic, '" alt="User" class="user-avatar-mini">',
 // 🚀 Displays the green online dot automatically when loaded in the inbox
 (conv.is_online ? '<div class="online-dot"></div>' : ''),
 '</div>',
 '<div class="flex-grow-1 d-flex flex-column justify-content-center" style="min-width:0;">',
 '<div class="d-flex justify-content-between align-items-center mb-1">',
 '<strong class="text-truncate text-dark" style="font-size: 14.5px;">', conv.other_fname, '</strong>',
 '<span class="text-muted flex-shrink-0 ms-2" style="font-size: 11px;">', timeStr, '</span>',
 '</div>',
 '<div class="d-flex align-items-center mb-1">',
 '<div class="text-truncate text-primary fw-bold" style="font-size: 12px;">', (conv.ad_title || ""), '</div>',
 statusBadge,
 '</div>',
 '<div class="d-flex justify-content-between align-items-center">',
 '<span class="text-truncate ', (isUnread ? 'fw-bold text-dark' : 'text-muted'), '" style="font-size: 13px;" id="sidebar-lastmsg-', conv.conversation_id, '">', snippet, '</span>',
 '<div class="d-flex align-items-center flex-shrink-0 ms-2 gap-2">',
 badgeHtml,
 '<div class="dropdown" onclick="event.stopPropagation()">',
 '<button class="btn btn-sm btn-link text-muted p-0 text-decoration-none border-0 fw-bolder" style="font-size: 20px; line-height: 1;" data-bs-toggle="dropdown">⋮</button>',
 '<ul class="dropdown-menu dropdown-menu-end shadow-sm border-0 rounded-3 py-1" style="font-size: 13px;">',
 spamAction,
 blockAction,
 '<li><a class="dropdown-item text-danger d-flex align-items-center gap-2 py-2 mt-1" href="#" onclick="event.stopPropagation(); window.deleteConversation(\\'' + conv.conversation_id + '\\')">',
 '<svg width="14" height="14" fill="currentColor" viewBox="0 0 16 16"><path d="M5.5 5.5A.5.5 0 0 1 6 6v6a.5.5 0 0 1-1 0V6a.5.5 0 0 1 .5-.5zm2.5 0a.5.5 0 0 1 .5.5v6a.5.5 0 0 1-1 0V6a.5.5 0 0 1 .5-.5zm3 .5a.5.5 0 0 0-1 0v6a.5.5 0 0 0 1 0V6z"/><path fill-rule="evenodd" d="M14.5 3a1 1 0 0 1-1 1H13v9a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V4h-.5a1 1 0 0 1-1-1V2a1 1 0 0 1 1-1H6a1 1 0 0 1 1-1h2a1 1 0 0 1 1 1h3.5a1 1 0 0 1 1 1v1zM4.contact via the original listingV13a1 1 0 0 0 1 1h6a1 1 0 0 0 1-1V4.059L11.882 4H4.118zM2.5 3V2h11v1h-11z"/></svg>',
 'Delete Chat',
 '</a></li>',
 '</ul>',
 '</div>',
 '</div>',
 '</div>',
 '</div>'
 ].join('');

 const currentUrlSegments = window.location.pathname.split('/').filter(Boolean);
 const isActive = currentUrlSegments[0] === 'messages' && currentUrlSegments[1] == conv.conversation_id;

 if (existing) {
 existing.innerHTML = html;
 if (isActive) existing.classList.add('active'); else existing.classList.remove('active');
 if (bumpToTop) listContainer.prepend(existing);
 } else {
 const div = document.createElement("div");
 div.className = "user-item" + (isActive ? " active" : "");
 div.dataset.conversationId = conv.conversation_id;
 div.innerHTML = html;
 if (bumpToTop) listContainer.prepend(div);
 else listContainer.appendChild(div);
 }
 };

 function initChatSidebar() {
 const listContainer = document.getElementById("chatListContainer");
 if (listContainer) {
 listContainer.addEventListener("scroll", () => {
 const st = window.ChatSidebarState;
 if (st.loading || st.allLoaded) return;
 if (listContainer.scrollTop + listContainer.clientHeight >= listContainer.scrollHeight - 40) {
 window.loadConversations(true);
 }
 });
 window.loadConversations();
 }
 }

 if (document.readyState === 'loading') {
 document.addEventListener("DOMContentLoaded", initChatSidebar);
 } else {
 setTimeout(initChatSidebar, 50);
 }
 </script>`;
}
